WITH cleaned AS (SELECT id, txn_type, txn_time, merchant, CAST(is_flagged AS INT) AS is_flagged_flag FROM transactions WHERE txn_time > TIMESTAMP '2023-06-20 18:00:00' AND merchant IS NOT NULL) SELECT txn_type, CASE WHEN is_flagged_flag >= 68 THEN 'LARGE' ELSE 'SMALL' END AS is_flagged_flag_tier, DATE_TRUNC('YEAR', txn_time) AS year_start, SIZE(COLLECT_SET(txn_type)) AS num_txn_types, ROUND(AVG(is_flagged_flag), 2) AS avg_is_flagged_flag FROM cleaned GROUP BY txn_type, is_flagged_flag_tier, year_start HAVING avg_is_flagged_flag > 0;
